using ComponentSpace.SAML2.Assertions;
using ComponentSpace.SAML2.Protocols;
using LoginService.Aplication.Interfaces.Saml;
using LoginService.Domain.Entities.Usuario;
using LoginService.Domain.Enums;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography.X509Certificates;
using System.Security.Cryptography.Xml;
using System.Text;
using System.Threading.Tasks;
using System.Xml;
using Utilities.Entities;
using Utilities.Entities.Logs;
using Utilities.Entities.Network;
using Utilities.Interfaces.Logs;
using Utilities.Metodos;

namespace LoginService.Infrastructure.Services.Saml
{
    public class SamlServices : ISamlService
    {
        private readonly IHttpContextAccessor _httpContextAccessor;
        private readonly IConfiguration _config;
        public SamlServices(IHttpContextAccessor httpContextAccessor, IConfiguration config)
        {
            _httpContextAccessor = httpContextAccessor;
            _config = config;

        }
        public Task<EntResultado<EntUsuario>> DevuelveParametrosOkta()
        {
            EntResultado<EntUsuario> result = new EntResultado<EntUsuario>();
            result.exito = false;
            var strScope = string.Empty;
            var request = _httpContextAccessor.HttpContext?.Request;
            EntUsuario objUsr = new EntUsuario();
            var rutaRelativa = _config["Certificado:RutaRelativa"];
            var password = _config["Certificado:Password"];
            try
            {
                //DALLogin objDALLogin = new DALLogin();
                InfoHostDns objInfo = new InfoHostDns(_httpContextAccessor);
                EntUInfoHostDns objInfoHostDns = objInfo.ObtenerInfoDNS();
                var XMLBase64 = request?.Form["SAMLResponse"]; //"";//request?.Form["SAMLResponse"];
                var byteAssertion = Convert.FromBase64String(XMLBase64);
                string XMLEncryptedAssertion = Encoding.UTF8.GetString(byteAssertion);

                XmlDocument XMLSAMLResponse = new XmlDocument();
                XMLSAMLResponse.LoadXml(XMLEncryptedAssertion);
                SAMLResponse samlResponse = new SAMLResponse(XMLSAMLResponse.DocumentElement);
                EncryptedAssertion encryptedAssertion = samlResponse.GetEncryptedAssertion();

                var rutaBase = AppContext.BaseDirectory;
                string rutaCompleta = Path.Combine(rutaBase, rutaRelativa);

                var ApplicationCertificate = new X509Certificate2(rutaCompleta, password);

                XmlElement decryptedAssertion = encryptedAssertion.DecryptToXml(ApplicationCertificate.PrivateKey);
                SAMLAssertion xmlAssertion = new SAMLAssertion(decryptedAssertion);
                var ListAttributeStatement = xmlAssertion.GetAttributeStatements().FirstOrDefault();
                var ListAttributes = ListAttributeStatement.Attributes;

                foreach (SAMLAttribute item in ListAttributes)
                {
                    switch (item.Name.Trim())
                    {
                        case "NumeroEmpleado":
                            objUsr.fnNumeroEmpleado = Convert.ToInt32(item.Values[0]);
                            break;
                        case "NombreEmpleado":
                            objUsr.fcNombre = item.Values[0].ToString();
                            break;
                        case "Empresa":
                            objUsr.fcEmpresa = item.Values[0].ToString();
                            break;
                        case "CentroCostos":
                            objUsr.fcCentroCostos = item.Values[0].ToString();
                            break;
                        case "Correo":
                            objUsr.fcCorreo = item.Values[0].ToString();
                            break;
                        case "Puesto":
                            objUsr.fcPuesto = item.Values[0].ToString();
                            break;
                    }
                }
                result.exito = true;
                result.data = objUsr;

                EntULogAcceso log = new EntULogAcceso
                {
                    fcLlaveMaestra = objUsr.fnNumeroEmpleado.ToString(),
                    fnTipoSession = 2,
                    fcIpMachine = objInfoHostDns.info_HostAddress,
                    fcTicketSession = "",
                    fnOpcion = (Int32)EunumAcceso.TiposAccessLogin.LOGIN
                };

            }
            catch (Exception ex)
            {
                result.exito = false;
                result.error = $"Ha ocurrito un error al obtener los datos de usuario: {ex.Message}";
                //CBL.Logs.BLLLogs.LogEscritura(ex.Message + "Scope: " + strScope);
            }
            return Task.FromResult(result); // o false según el resultado;
        }
    }
}
